from rules import solve_versions


def solve(data):
    return solve_versions(data)

def _interval(value):
    if value is None:
        return None, None
    if isinstance(value, (list, tuple)) and len(value) == 2:
        return value[0], value[1]
    if isinstance(value, int):
        return value, value
    return None, None


def _dependency(item):
    if isinstance(item, str):
        return item, (None, None)
    if isinstance(item, dict):
        name = item.get('name', item.get('package', item.get('pkg')))
        if name is None and len(item) == 1:
            name, value = next(iter(item.items()))
            return name, _interval(value)
        if name is None:
            return None, (None, None)
        if 'range' in item:
            bounds = _interval(item['range'])
        elif 'versions' in item:
            bounds = _interval(item['versions'])
        elif 'version' in item:
            bounds = _interval(item['version'])
        else:
            bounds = (item.get('min'), item.get('max'))
        return name, bounds
    if isinstance(item, (list, tuple)) and item:
        name = item[0]
        if len(item) == 2:
            bounds = _interval(item[1])
        elif len(item) >= 3:
            bounds = (item[1], item[2])
        else:
            bounds = (None, None)
        return name, bounds
    return None, (None, None)


def _merge(old, new):
    low, high = old
    other_low, other_high = new
    if other_low is not None and (low is None or other_low > low):
        low = other_low
    if other_high is not None and (high is None or other_high < high):
        high = other_high
    if low is not None and high is not None and low > high:
        return None
    return low, high


def _acyclic(graph):
    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[node] = 1
        for neighbor in graph.get(node, ()):
            if not visit(neighbor):
                return False
        state[node] = 2
        return True

    nodes = set(graph)
    for neighbors in graph.values():
        nodes.update(neighbors)
    return all(visit(node) for node in nodes)


def solve_versions(data):
    packages = data['packages']
    names = sorted(packages)
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    constraints = {}

    for name, interval in data['roots'].items():
        if name not in packages:
            return {'error': 'unsatisfiable'}
        merged = _merge(constraints.get(name, (None, None)), _interval(interval))
        if merged is None:
            return {'error': 'unsatisfiable'}
        constraints[name] = merged

    best_score = None
    best_versions = None
    seen = set()

    def search(selected, required, graph):
        nonlocal best_score, best_versions
        graph_state = tuple(
            (name, tuple(sorted(neighbors)))
            for name, neighbors in sorted(graph.items())
        )
        state = (
            tuple(sorted(selected.items())),
            tuple(sorted(required.items())),
            graph_state,
        )
        if state in seen:
            return
        seen.add(state)

        unresolved = [name for name in required if name not in selected]
        if not unresolved:
            score = tuple(selected.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(selected)
            return

        name = min(unresolved)
        if name not in packages:
            return
        low, high = required[name]
        forbidden = blocked.get(name, ())

        for row in packages[name]:
            version = row['version']
            if low is not None and version < low:
                continue
            if high is not None and version > high:
                continue
            if version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue

            next_selected = dict(selected)
            next_selected[name] = version
            next_required = dict(required)
            next_graph = {key: set(value) for key, value in graph.items()}
            next_graph.setdefault(name, set())
            valid = True

            for item in row.get('deps', []):
                if isinstance(item, dict):
                    feature = item.get('feature')
                    if feature and feature not in features:
                        continue

                dep_name, bounds = _dependency(item)
                if dep_name is None:
                    valid = False
                    break

                merged = _merge(next_required.get(dep_name, (None, None)), bounds)
                if merged is None:
                    valid = False
                    break
                next_required[dep_name] = merged
                next_graph[name].add(dep_name)

                if dep_name in next_selected:
                    dep_version = next_selected[dep_name]
                    if ((merged[0] is not None and dep_version < merged[0]) or
                            (merged[1] is not None and dep_version > merged[1])):
                        valid = False
                        break

            if valid and _acyclic(next_graph):
                search(next_selected, next_required, next_graph)

    search({}, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
